class Breaker:
    """After 5 straight DynamoDB failures stop calling it for 5 s (saves every request 25 ms of waiting)."""
    def __init__(self):
        self.calls = deque()
        self.fails = 0
        self.open_until = 0.0    

    def allow(self):
        return time.monotonic() >= self.open_until

    def ok(self):
        self._record(False)

    def fail(self):
        self._record(True)

    def _record(self, failed):
        now = time.monotonic()
        self.calls.append((now, failed))
        self.fails += failed
        while self.calls[0][0] < now - BREAKER_WINDOW_S:      # drop calls older than the window
            self.fails -= self.calls.popleft()[1]
        if self.fails >= BREAKER_FAILS and self.fails >= BREAKER_RATE * len(self.calls):
            self.open_until = now + BREAKER_OPEN_S
            self.calls.clear()                                # start fresh when it reopens
            self.fails = 0

class State:
    pass


S = State()
M = defaultdict(float)          # metrics


def _fetch(token):
    r = S.ddb.get_item(TableName=TABLE, Key={"card_token": {"S": token}}, ConsistentRead=True)
    it = r.get("Item")
    return parse_item(it) if it else None


def _release_slot(_fut):
    """CHANGED: called when the DynamoDB read really finishes (or is cancelled), not when we stop waiting.
    A timed-out read keeps its thread busy, so its slot must stay taken until the thread is free."""
    S.slots.release()


def _model_for(cfg):
    path = cfg["ml"]["model_path"]
    if path != S.model_path:                  # config change = model deploy / rollback
        try:
            S.model, S.model_path = Model.load(path), path
            print(f"[model] loaded {path} ({S.model.version})", flush=True)
        except Exception as e:
            print(f"[model] could not load {path}: {e}; keeping previous", flush=True)
            S.model_path = path if S.model is None else S.model_path
    return S.model


@asynccontextmanager
async def lifespan(app):
    S.cfg = LiveConfig(CONFIG_PATH)
    S.ddb = client("dynamodb", fast=True)
    S.ddb_admin = client("dynamodb")          # CHANGED (C4): normal timeouts; verify is off the 50 ms path
    S.pool = ThreadPoolExecutor(max_workers=POOL_SIZE)   # CHANGED: uses the shared constant
    S.slots = threading.BoundedSemaphore(POOL_SIZE)      # CHANGED: one slot per worker thread
    S.breaker = Breaker()
    S.pub = Publisher(client("kinesis"), STREAM)
    S.idem = OrderedDict()                    # Idempotency-Key -> reply (retries get the same answer)
    S.local = defaultdict(lambda: deque(maxlen=50))   # this pod's recent decisions per card
    S.local_touched, S.model, S.model_path = {}, None, None
    if not STEPUP_SECRET:                     # CHANGED (C4): fail safe, never sign with an empty key
        print("[stepup] STEPUP_SECRET not set: no challenge tokens, verify returns 503", flush=True)
    _model_for(S.cfg.get())
    yield


app = FastAPI(lifespan=lifespan)


