@app.post("/v1/decide")
async def decide(txn: Txn, request: Request):
    t0 = time.perf_counter()
    key = request.headers.get("Idempotency-Key") or txn.transaction_id
    if key in S.idem:
        M["idempotent_hits"] += 1
        return S.idem[key]

    cfg = S.cfg.get()
    d = txn.model_dump()
    item, reason = None, None
    if not S.breaker.allow():
        reason = "FALLBACK_STORE_DOWN"
    elif not S.slots.acquire(blocking=False):     # CHANGED: every thread is stuck on a slow read
        reason = "FALLBACK_STORE_BUSY"            #          so answer now instead of queueing
    else:
        try:
            fut = S.pool.submit(_fetch, txn.card_token)
            fut.add_done_callback(_release_slot)  # CHANGED: frees the slot when the thread is really done
            item = await asyncio.wait_for(asyncio.wrap_future(fut),
                                          timeout=cfg["feature_timeout_ms"] / 1000)
            S.breaker.ok()
        except asyncio.TimeoutError:
            S.breaker.fail()
            reason = "FALLBACK_TIMEOUT"
        except Exception as e:                    # CHANGED: was "except Exception:", so "e" was undefined
            S.breaker.fail()
            reason = "FALLBACK_STORE_ERROR"
            M["STORE_ERRORS_LOGGED"] += 1
            if M["STORE_ERRORS_LOGGED"] <= MAX_ERROR_LOGS:
                print(f"[store] {type(e).__name__}: {e}", flush=True)   # CHANGED: indentation fixed

    if reason:
        res = fallback_decision(d, cfg, reason)
        M["fallback_" + reason] += 1
    else:
        elapsed_ms = (time.perf_counter() - t0) * 1000
        skip_ml = elapsed_ms > cfg["total_budget_ms"] * 0.8      # nearly out of time: rules only
        if skip_ml:
            M["ml_skipped"] += 1
        if item is None:
            M["no_history"] += 1
        ets = parse_ts(txn.event_time)
        local = [(ts, i) for ts, i in S.local[txn.card_token] if ets - 300 <= ts <= ets]
        res = decide_core(d, item, local, cfg, _model_for(cfg), time.time(), skip_ml)
        S.local[txn.card_token].append((ets, txn.transaction_id))
        S.local_touched[txn.card_token] = time.monotonic()
        if len(S.local_touched) > 50000:                          # sweep idle cards
            cutoff = time.monotonic() - 600
            for tok in [k for k, v in S.local_touched.items() if v < cutoff]:
                S.local_touched.pop(tok, None)
                S.local.pop(tok, None)
        f = res["features"]
        if f and f["feature_age_s"] is not None:
            M["feature_age_s_sum"] += f["feature_age_s"]
            M["feature_age_s_count"] += 1

    latency = (time.perf_counter() - t0) * 1000
    reply = {"decision": res["decision"], "score": res["score"], "reasons": res["reasons"],
             "fallback": res["fallback"], "latency_ms": round(latency, 2)}
    if res["decision"] == "STEP_UP":
        reply["challenge"] = "3DS_OTP_STUB"            # [10] would hand over to the 3-D Secure ACS here
        if STEPUP_SECRET:                               # CHANGED (C4): binds card + device + expiry
            reply["challenge_token"] = stepup.sign(txn.card_token, txn.device_id, txn.transaction_id,
                                                   time.time(), STEPUP_TTL_S, STEPUP_SECRET)
    if res.get("shadow"):
        reply["shadow_decision"] = res["shadow"]

    # [11] record for Flink-replacement / consumers: never awaited
    S.pub.submit({
        "event_id": txn.transaction_id, "event_time": txn.event_time, "card_token": txn.card_token,
        "amount_minor": txn.amount_minor, "channel": txn.channel, "merchant": d["merchant"],
        "device_id": txn.device_id, "decision": res["decision"], "score": res["score"],
        "shadow_decision": res.get("shadow"), "reasons": res["reasons"], "fallback": res["fallback"],
        "features": res["features"], "decided_at": time.time()})

    M["decisions_" + res["decision"]] += 1
    M["latency_ms_sum"] += latency
    M["latency_ms_count"] += 1
    if latency > cfg["total_budget_ms"]:
        M["over_budget"] += 1
    S.idem[key] = reply
    if len(S.idem) > 20000:
        S.idem.popitem(last=False)
    return reply


def _reject(metric):
    """CHANGED (C4): one generic answer for every failure, so a caller can't tell which check failed."""
    M["stepup_" + metric] += 1
    raise HTTPException(status_code=400, detail="challenge not accepted")


def _conditional(call, metric, **kw):
    """CHANGED (C4): conditional DynamoDB write. Condition failed -> generic 400; other AWS error -> 503."""
    try:
        call(**kw)
    except ClientError as e:
        if e.response["Error"]["Code"] == "ConditionalCheckFailedException":
            _reject(metric)
        print(f"[stepup] store error: {e.response['Error']['Code']}", flush=True)   # no token/card in logs
        raise HTTPException(status_code=503, detail="try again later") from None


@app.post("/v1/stepup/verify")
def stepup_verify(req: VerifyReq):
    """CHANGED (C4): a plain def, so FastAPI runs it in its own threads, away from the decide path.
    Order: signature + expiry -> burn the challenge (one attempt only) -> OTP -> trust the device."""
    if not STEPUP_SECRET:
        raise HTTPException(status_code=503, detail="step-up not configured")
    try:
        claim = stepup.verify(req.token, time.time(), STEPUP_SECRET)   # device comes from the TOKEN
    except stepup.InvalidChallenge:
        _reject("bad_token")
    _conditional(S.ddb_admin.put_item, "reused", TableName=USED_TABLE,
                 ConditionExpression="attribute_not_exists(jti)",
                 Item={"jti": {"S": claim["jti"]}, "expires_at": {"N": str(claim["exp"] + 86400)}})
    if not stepup.otp_ok(req.otp, STEPUP_OTP):         # checked AFTER burning: no second guess
        _reject("bad_otp")
    _conditional(S.ddb_admin.update_item, "refused", TableName=TABLE,
                 Key={"card_token": {"S": claim["card"]}},
                 UpdateExpression="ADD known_devices :d",            # touches only this one field
                 ConditionExpression="attribute_exists(card_token) AND "
                                     "(attribute_not_exists(blocked) OR blocked = :f)",
                 ExpressionAttributeValues={":d": {"SS": [claim["dev"]]}, ":f": {"BOOL": False}})
    M["stepup_verified"] += 1
    return {"status": "verified"}


@app.get("/metrics", response_class=PlainTextResponse)
def metrics():
    lines = [f"fraud_{k.lower()} {v}" for k, v in sorted(M.items())]
    lines += [f"fraud_publish_sent {S.pub.sent}", f"fraud_publish_failed {S.pub.failed}",
              f"fraud_publish_dropped {S.pub.dropped}", f"fraud_publish_queue {S.pub.q.qsize()}",
              f"fraud_breaker_open {int(not S.breaker.allow())}"]
    return "\n".join(lines) + "\n"
